use super::*;

// Authored literal bytes are public source fixtures, never read from private
// docs or generated by the production serializer. Whitespace is not canonical.
const BINDING: &str = include_str!("binding-v1.json");
const ENROLLMENT: &str = include_str!("enrollment-v1.json");
const ROUTINE_BINDING: &str = include_str!("routine-binding-v1.json");

fn reference(domain: &[u8], bytes: &[u8]) -> [u8; 32] {
    let mut hash = blake3::Hasher::new();
    hash.update(domain);
    hash.update(bytes);
    *hash.finalize().as_bytes()
}
#[test]
fn decision_binding_golden_bytes_and_domain_digest() {
    let expected = BINDING.trim_end().as_bytes();
    let b = binding();
    assert_eq!(b.canonical_bytes().unwrap(), expected);
    let expected_digest = reference(b"koru.bot.decision.binding.v1", expected);
    assert_eq!(*b.digest().unwrap().as_bytes(), expected_digest);
    assert_ne!(
        expected_digest,
        reference(b"koru.bot.decision.binding.v1\0", expected)
    );
    println!(
        "binding golden digest: {}",
        String::from(DecisionDigest::from_bytes(expected_digest))
    );
}
#[test]
fn decision_enrollment_golden_bytes_and_domain_digest() {
    let expected = ENROLLMENT.trim_end().as_bytes();
    let v = intent();
    assert_eq!(v.canonical_bytes().unwrap(), expected);
    let expected_digest = reference(b"koru.bot.decision.wait-enrollment.v1", expected);
    assert_eq!(*v.digest().unwrap().as_bytes(), expected_digest);
    assert_ne!(
        expected_digest,
        reference(b"koru.bot.decision.binding.v1", expected)
    );
    println!(
        "enrollment golden digest: {}",
        String::from(DecisionDigest::from_bytes(expected_digest))
    );
}
#[test]
fn decision_enrollment_hash_binds_exact_frozen_revisions_and_cause() {
    let i = intent();
    let original = i.digest().unwrap();
    let mut changed = i.clone();
    changed.wait_revision = rev(4);
    assert_ne!(changed.digest().unwrap(), original);
    let mut changed = i;
    changed.origin_turn = id(99);
    assert_ne!(changed.digest().unwrap(), original);
    let mut raw = json(&intent());
    raw["cause"] = "run".into();
    assert!(decode::<BotWaitCleanupIntentV1>(&raw).is_err());
}

#[test]
fn decision_routine_binding_golden_preserves_full_claim_and_route() {
    let expected = ROUTINE_BINDING.trim_end().as_bytes();
    let b = routine_binding();
    assert_eq!(b.canonical_bytes().unwrap(), expected);
    let expected_digest = reference(b"koru.bot.decision.binding.v1", expected);
    assert_eq!(*b.digest().unwrap().as_bytes(), expected_digest);
    println!(
        "routine binding golden digest: {}",
        String::from(DecisionDigest::from_bytes(expected_digest))
    );
}
